# -*- coding: utf-8 -*-
"""Serviços e gerenciamento de redes (SERV) — cota 21."""
from comum import Q

E = "SERV"
QUESTOES = [
    # ---------------- variações ----------------
    Q(E, "04", 22, sub="22.2", pai="ESP-SERV-0001", k="srv-pushgateway",
      enun="Um job noturno de conciliação roda por poucos minutos e termina antes que o Prometheus faça a próxima coleta, de modo que suas métricas nunca são raspadas. O componente do ecossistema Prometheus indicado para esse caso é o",
      alts=["Alertmanager.",
            "node_exporter.",
            "Pushgateway, para o qual o job envia as métricas, que depois são coletadas pelo Prometheus.",
            "Grafana, que armazena as métricas enviadas pelo job.",
            "Logstash, com filtro grok."],
      gab="C",
      com="**Gabarito: C.** O Prometheus é **pull** (raspa `/metrics`); para **jobs curtos** que terminam antes da coleta, existe o **Pushgateway**: o job \"empurra\" as métricas para ele, e o Prometheus as raspa ali.\n\n(A) O Alertmanager roteia e agrupa alertas. (B) O node_exporter expõe métricas do sistema operacional do host. (D) O Grafana só visualiza; não armazena métricas. (E) Logstash processa logs."),

    Q(E, "04", 22, sub="22.2", pai="ESP-SERV-0002", k="srv-elk-papeis",
      enun="Em uma pilha Elastic (ELK) de logs, os componentes responsáveis, respectivamente, por receber e transformar os eventos, por indexá-los e permitir buscas, e por exibi-los em painéis são",
      alts=["Kibana, Logstash e Elasticsearch.",
            "Elasticsearch, Kibana e Logstash.",
            "Logstash, Kibana e Elasticsearch.",
            "Logstash, Elasticsearch e Kibana.",
            "Fluentd, Grafana e Prometheus."],
      gab="D",
      com="**Gabarito: D.** **Logstash** recebe e transforma (input → filter → output); **Elasticsearch** indexa e busca; **Kibana** visualiza.\n\n(A), (B) e (C) trocam os papéis. (E) Fluentd é coletor (forma o EFK no lugar do Logstash), mas Grafana e Prometheus pertencem à pilha de métricas."),

    Q(E, "04", 22, sub="22.2", pai="ESP-SERV-0003", k="srv-ferramentas-correta",
      enun="Sobre ferramentas de monitoramento e logs, é correto afirmar:",
      alts=["o Grafana coleta métricas dos servidores por meio de agentes próprios e as armazena em seu banco de séries temporais.",
            "o Kibana é o mecanismo de indexação e busca do Elastic Stack.",
            "o Prometheus usa por padrão o modelo push, em que cada aplicação envia métricas ao servidor.",
            "o Zabbix exige obrigatoriamente agentes instalados, pois não suporta SNMP.",
            "o Fluentd é um coletor de logs com plugins de entrada e saída, usado no stack EFK, comum em Kubernetes."],
      gab="E",
      com="**Gabarito: E.** O **Fluentd** (CNCF) é uma camada unificada de logging com plugins; com Elasticsearch e Kibana forma o **EFK**. O Fluent Bit é a versão mais leve.\n\n(A) O Grafana não coleta nem armazena: conecta-se a fontes de dados. (B) Quem indexa é o Elasticsearch; o Kibana visualiza. (C) O Prometheus é **pull**. (D) O Zabbix suporta agentes e também coleta agentless, SNMP, IPMI e JMX."),

    Q(E, "04", 22, sub="22.2", pai="ESP-SERV-0004", k="srv-zabbix-proxy", mv="C",
      enun="Um banco monitora com Zabbix os equipamentos de 80 agências ligadas à matriz por enlaces WAN. Para coletar os dados localmente em cada região, reduzir o tráfego na WAN e continuar coletando mesmo durante quedas temporárias do enlace, enviando tudo depois ao servidor central, utiliza-se",
      alts=["o Zabbix proxy.",
            "uma trigger.",
            "um template.",
            "um host group.",
            "o Pushgateway."],
      gab="A",
      com="**Gabarito: A.** O **Zabbix proxy** coleta em nome do servidor em redes remotas, armazena temporariamente os dados e os repassa ao servidor central.\n\n(B) Trigger é a condição de alerta. (C) Template é um modelo reaproveitável de itens, triggers e gráficos. (D) Host group só agrupa hosts. (E) Pushgateway é do ecossistema Prometheus."),

    Q(E, "04", 22, sub="22.1", pai="ESP-SERV-0005", k="srv-monit-observ",
      enun="Sobre monitoramento e observabilidade, é correto afirmar que",
      alts=["monitoramento e observabilidade são sinônimos e dispensam logs.",
            "o monitoramento acompanha indicadores conhecidos e alerta quando saem do normal, enquanto a observabilidade é a capacidade de entender o estado interno do sistema a partir do que ele emite, inclusive para problemas não previstos.",
            "a observabilidade se limita a verificar se o servidor responde ao ping.",
            "o MTTD mede o tempo médio entre falhas, e o MTTR, o tempo médio de detecção.",
            "o OpenTelemetry é uma ferramenta exclusiva para coletar logs de Windows Server."],
      gab="B",
      com="**Gabarito: B.** **Monitoramento** responde a perguntas conhecidas (\"o servidor está no ar?\"); **observabilidade** permite investigar o desconhecido (\"por que esta requisição está lenta?\"), a partir de logs, métricas e traces.\n\n(A) São conceitos distintos, e logs são um dos pilares. (C) Isso é monitoramento básico de disponibilidade. (D) MTTD = tempo médio para **detectar**; MTTR = tempo médio para reparar/recuperar. (E) O OpenTelemetry é padrão aberto para coletar logs, métricas e traces."),

    Q(E, "04", 24, sub="24.1", pai="ESP-SERV-0006", k="srv-h323",
      enun="Em uma solução de videoconferência baseada na recomendação H.323 da ITU-T, o componente que controla a admissão das chamadas, faz a tradução de endereços e gerencia a banda da zona, e o componente que permite conferências com três ou mais participantes são, respectivamente,",
      alts=["proxy SIP e registrar.",
            "gateway e terminal.",
            "MCU e gatekeeper.",
            "gatekeeper e MCU.",
            "RTP e RTCP."],
      gab="D",
      com="**Gabarito: D.** No H.323, o **gatekeeper** controla admissão, tradução de endereços e banda (sinalização RAS); a **MCU** (Multipoint Control Unit) viabiliza conferências multiponto.\n\n(A) Proxy e registrar são componentes do SIP. (B) O gateway faz a interconexão com outras redes (ex.: telefonia pública) e o terminal é o ponto final. (C) Inverte os papéis. (E) RTP transporta a mídia e RTCP traz estatísticas."),

    Q(E, "04", 24, sub="24.1", pai="ESP-SERV-0006", k="srv-rtp-sdp",
      enun="Em uma chamada VoIP baseada em SIP, os protocolos responsáveis, respectivamente, por descrever a sessão (codecs e portas negociados), por transportar o áudio e por enviar estatísticas de qualidade da mídia são",
      alts=["SDP, RTP e RTCP.",
            "RTP, SDP e SIP.",
            "H.245, H.225 e RAS.",
            "SIP, TCP e SNMP.",
            "SDP, RTCP e RTP."],
      gab="A",
      com="**Gabarito: A.** O **SDP** (dentro do SIP) descreve a sessão; o **RTP** (sobre UDP) transporta a mídia; o **RTCP** traz estatísticas de qualidade.\n\n(B) Troca as funções e o SIP é sinalização, não estatística. (C) São partes do H.323 (controle de mídia, sinalização e RAS). (D) TCP não é usado para a mídia em tempo real e SNMP é gerenciamento. (E) Inverte RTP e RTCP."),

    Q(E, "04", 24, sub="24.2", pai="ESP-SERV-0007", k="srv-qos-voz", mv="E",
      enun="Ao dimensionar a rede de uma central de atendimento com telefonia IP, a equipe precisa respeitar os requisitos de qualidade da voz. É correto afirmar que",
      alts=["a voz tolera perdas de até 20% sem degradação perceptível, por isso dispensa priorização.",
            "o atraso fim a fim de até cerca de 150 ms em um sentido é considerado bom (ITU-T G.114), e jitter e perda devem ser mantidos baixos.",
            "o jitter não afeta a voz, pois o RTP retransmite os pacotes atrasados.",
            "o tráfego de voz deve ser marcado como best effort (DSCP 0) para não prejudicar os dados.",
            "o IntServ com RSVP é a técnica de QoS mais usada em larga escala, por reservar recursos por fluxo."],
      gab="B",
      com="**Gabarito: B.** Voz é sensível a **atraso, jitter e perda**: até ~**150 ms** em um sentido é bom (G.114), perda abaixo de ~1%, jitter baixo — por isso recebe prioridade (DSCP EF, filas LLQ).\n\n(A) Perdas desse nível degradam muito a voz. (C) O RTP não retransmite; usa-se buffer de jitter. (D) Voz deve ser marcada como EF (DSCP 46). (E) O IntServ/RSVP é pouco usado em larga escala; o DiffServ é o mais comum."),

    Q(E, "04", 24, sub="24.3", pai="ESP-SERV-0008", k="srv-igmp-snooping", mv="E",
      enun="Uma rede de agências transmite treinamentos em vídeo por multicast. Os switches de acesso estavam inundando todas as portas com esse tráfego. Para que cada switch envie o fluxo multicast apenas às portas cujos hosts pediram para participar do grupo, deve-se habilitar",
      alts=["o PIM nos computadores dos usuários.",
            "o broadcast dirigido na VLAN de vídeo.",
            "o MLD nos hosts IPv4.",
            "o IGMP snooping nos switches.",
            "o protocolo STP nas portas de acesso."],
      gab="D",
      com="**Gabarito: D.** Com **IGMP snooping**, o switch \"escuta\" as mensagens IGMP entre hosts e roteador e encaminha o multicast só às portas interessadas.\n\n(A) O PIM roda **entre roteadores**. (B) Broadcast aumentaria a inundação. (C) O MLD é o equivalente do IGMP para **IPv6**. (E) O STP evita laços, sem relação com a seleção de portas de multicast."),

    Q(E, "04", 24, sub="24.4", pai="ESP-SERV-0009", k="srv-vxlan-calc", tags=["calculo"],
      enun="Em um data center multi-inquilino, o limite de VLANs IEEE 802.1Q (VID de 12 bits) se tornou insuficiente, e a equipe adotou VXLAN, cujo identificador de segmento (VNI) tem 24 bits. O número teórico de segmentos VXLAN e o protocolo/porta usados no encapsulamento são, respectivamente,",
      alts=["4.096 segmentos, sobre TCP 4789.",
            "65.536 segmentos, sobre UDP 4789.",
            "16.777.216 segmentos, sobre TCP 179.",
            "16.777.216 segmentos, sobre UDP 4789.",
            "1.048.576 segmentos, sobre UDP 5060."],
      gab="D",
      com="**Gabarito: D.** 2²⁴ = **16.777.216** identificadores (cerca de 16 milhões, contra 4.094 VLANs úteis); a VXLAN encapsula quadros de camada 2 em **UDP 4789**.\n\n(A) 4.096 = 2¹² é o espaço da VLAN, e o transporte não é TCP. (B) 65.536 = 2¹⁶. (C) TCP 179 é a porta do BGP. (E) 2²⁰ e a porta 5060 (SIP) não se aplicam.\n\nConta conferida em `tools/verificacao/agente4/verif_serv.py`."),

    Q(E, "04", 25, sub="25.2", pai="ESP-SERV-0010", k="srv-apache-proxy",
      enun="Um Apache HTTP Server será colocado na frente de três instâncias WildFly para terminar o TLS e distribuir as requisições entre elas. Os módulos do Apache diretamente envolvidos nessa configuração são",
      alts=["mod_ssl, mod_proxy e mod_proxy_balancer.",
            "mod_rewrite e o MPM prefork apenas.",
            "mod_headers e .htaccess.",
            "o pool de aplicativos e o binding HTTPS.",
            "o modo domain e o domain controller."],
      gab="A",
      com="**Gabarito: A.** **mod_ssl** fornece HTTPS (terminação TLS); **mod_proxy** e **mod_proxy_balancer** fazem o proxy reverso e o balanceamento entre os servidores de aplicação.\n\n(B) mod_rewrite reescreve URLs e o MPM define o modelo de processos/threads; não balanceiam. (C) mod_headers manipula cabeçalhos e .htaccess é configuração por diretório. (D) Pool de aplicativos e binding são conceitos do IIS. (E) Modo domain é do WildFly/JBoss EAP."),

    Q(E, "04", 25, sub="25.3", pai="ESP-SERV-0011", k="srv-iis-binding",
      enun="No IIS, dois sites (`portal.banco.local` e `intranet.banco.local`) precisam responder no mesmo endereço IP e na mesma porta 443. Para isso, cada site deve ter configurado um(a)",
      alts=["pool de aplicativos diferente apenas.",
            "binding com o nome de host (host header) correspondente, com SNI para o certificado TLS.",
            "arquivo .htaccess na raiz do site.",
            "MPM event no lugar do prefork.",
            "VirtualHost no httpd.conf."],
      gab="B",
      com="**Gabarito: B.** No IIS, o **binding** combina protocolo, IP, porta e **nome de host**; com HTTPS, o **SNI** permite escolher o certificado de cada nome no mesmo IP e porta.\n\n(A) O pool isola processos, mas não define qual site atende cada nome. (C), (D) e (E) São conceitos do Apache HTTP Server, não do IIS."),

    Q(E, "04", 25, sub="25.4", pai="ESP-SERV-0013", k="srv-wildfly-standalone",
      enun="Um WildFly executado no modo standalone tem sua configuração principal no arquivo ______, console de administração na porta padrão ______, e aplicações podem ser implantadas copiando o `.war` para a pasta ______. As lacunas são preenchidas, respectivamente, por",
      alts=["domain.xml; 8080; webapps",
            "httpd.conf; 9990; htdocs",
            "standalone.xml; 9990; deployments",
            "web.config; 8443; wwwroot",
            "host.xml; 8080; lib"],
      gab="C",
      com="**Gabarito: C.** No modo **standalone**, a configuração fica em **standalone.xml**; o console de administração usa a porta **9990**; e o scanner automático implanta o que é copiado para **deployments** (também é possível usar o console ou a `jboss-cli`). As aplicações atendem por padrão na 8080.\n\n(A) domain.xml é do modo domain e webapps é do Tomcat. (B) httpd.conf e htdocs são do Apache. (D) web.config e wwwroot são do IIS. (E) host.xml é do modo domain."),

    # ---------------- inéditas ----------------
    Q(E, "04", 16, sub="16.10", top="SNMP, agentes, gerentes e MIBs", k="srv-snmp-trap",
      enun="No gerenciamento de redes com SNMP, a mensagem enviada espontaneamente pelo agente de um switch ao gerente, sem que tenha havido consulta, para comunicar, por exemplo, que uma interface caiu, é o",
      alts=["GET.",
            "GETNEXT.",
            "SET.",
            "RESPONSE.",
            "TRAP."],
      gab="E",
      com="**Gabarito: E.** O **TRAP** (e o INFORM, com confirmação, a partir da v2c) é a notificação **espontânea** do agente ao gerente, usando a porta UDP 162.\n\n(A) e (B) GET e GETNEXT são consultas do gerente (porta 161 do agente). (C) SET altera um valor no agente. (D) RESPONSE é a resposta do agente a uma consulta."),

    Q(E, "04", 16, sub="16.10", top="SNMP, agentes, gerentes e MIBs", k="srv-snmp-v3",
      enun="Sobre o SNMP, é correto afirmar:",
      alts=["as variáveis gerenciáveis de um dispositivo são descritas na MIB e identificadas por OIDs; as versões v1 e v2c usam community strings em texto claro, e a v3 acrescenta autenticação e criptografia.",
            "o agente roda na estação de gerência e o gerente roda em cada equipamento monitorado.",
            "o SNMP usa TCP 443 para garantir a confidencialidade desde a versão 1.",
            "a community \"public\" é recomendada em produção, por ser a padrão de fábrica.",
            "a MIB é o protocolo de transporte usado entre gerente e agente."],
      gab="A",
      com="**Gabarito: A.** A **MIB** descreve as variáveis, identificadas por **OIDs**; **v1/v2c** usam community strings em texto claro (inseguras), e o **SNMPv3** acrescenta autenticação e criptografia.\n\n(B) Inverte: o agente fica no dispositivo; o gerente, na estação de gerência. (C) O SNMP usa UDP 161/162; a v1 não tem criptografia. (D) A community \"public\" é um risco clássico e deve ser trocada ou abandonada em favor da v3. (E) A MIB é uma base de informações, não um protocolo."),

    Q(E, "04", 23, sub="23.4", top="Métodos de avaliação de desempenho: RFC 2544 e RFC 2889", k="srv-rfc2889",
      enun="Para homologar novos switches de acesso, uma equipe quer medir a taxa de encaminhamento, o comportamento sob congestionamento, a capacidade da tabela de endereços MAC, a taxa de aprendizado de endereços e o encaminhamento de broadcast. A metodologia de benchmark específica para esse tipo de dispositivo é a",
      alts=["RFC 2544, voltada apenas a links WAN.",
            "RFC 2889, metodologia de benchmark para dispositivos de comutação de LAN.",
            "ABNT NBR 14565:2019.",
            "ITU-T G.114.",
            "IEEE 802.3af."],
      gab="B",
      com="**Gabarito: B.** A **RFC 2889** é específica para **switches LAN**: taxa de encaminhamento, congestionamento, capacidade e aprendizado da tabela MAC, broadcast. A **RFC 2544** é a metodologia geral para dispositivos de interconexão (vazão, latência, perda de quadros, back-to-back).\n\n(A) A RFC 2544 não se limita a WAN, e o pedido é específico de switching. (C) A NBR 14565 trata de cabeamento estruturado. (D) G.114 trata de atraso em voz. (E) 802.3af é PoE."),

    Q(E, "04", 16, sub="16.10", top="Serviços de rede: proxy, e-mail e DHCP", k="srv-proxy-forward-reverse",
      enun="Na rede de um banco, o servidor A intermedeia o acesso dos funcionários à internet, aplicando filtros de conteúdo, autenticação e cache; o servidor B fica na frente dos servidores web do internet banking, recebendo as conexões dos clientes, terminando o TLS e distribuindo a carga. A e B são, respectivamente,",
      alts=["proxy reverso e proxy direto (forward).",
            "servidor DHCP e servidor DNS.",
            "proxy direto (forward) e proxy reverso.",
            "IDS e IPS.",
            "gateway VoIP e MCU."],
      gab="C",
      com="**Gabarito: C.** O **proxy direto (forward)** atende os **clientes internos** no acesso à internet (controle, filtragem, cache — ex.: Squid); o **proxy reverso** fica **na frente dos servidores** (balanceamento, terminação TLS, cache, WAF — ex.: Nginx, HAProxy).\n\n(A) Inverte os papéis. (B) DHCP e DNS não intermedeiam conexões HTTP. (D) IDS e IPS detectam/bloqueiam ataques. (E) São componentes de telefonia e videoconferência."),

    Q(E, "04", 11, sub="11.4", top="Serviços de rede: proxy, e-mail e DHCP", k="srv-spf-dkim",
      enun="Para reduzir a falsificação de e-mails com o domínio `banco.com.br` em campanhas de phishing, o administrador publicou no DNS registros que indicam quais servidores podem enviar mensagens pelo domínio, a chave pública usada para verificar a assinatura das mensagens e a política a aplicar quando essas verificações falham. Esses mecanismos, publicados em registros TXT, são",
      alts=["MX, PTR e SOA.",
            "POP3, IMAP e SMTP.",
            "SPF, DKIM e DMARC.",
            "A, AAAA e CNAME.",
            "LDAP, Kerberos e NTLM."],
      gab="C",
      com="**Gabarito: C.** **SPF** lista os servidores autorizados a enviar pelo domínio; **DKIM** publica a chave pública para verificar a assinatura das mensagens; **DMARC** define a política (nenhuma ação, quarentena, rejeição) e os relatórios. Todos usam registros **TXT**.\n\n(A) MX indica os servidores que recebem e-mail do domínio; PTR faz resolução reversa; SOA define a autoridade da zona. (B) São protocolos de acesso e envio de e-mail. (D) São registros de endereço e apelido. (E) São protocolos de diretório e autenticação."),

    Q(E, "04", 11, sub="11.5", top="Serviços de rede: proxy, e-mail e DHCP", k="srv-dhcp-relay",
      enun="O servidor DHCP de uma empresa fica na VLAN de servidores (10.10.1.0/24). Os computadores da VLAN de uma nova agência (10.20.5.0/24) não recebem endereço e acabam com IPs 169.254.x.x. A causa provável e a solução são:",
      alts=["o escopo está cheio; deve-se criar exclusões.",
            "o DNS está sem zona reversa; deve-se criar a zona in-addr.arpa.",
            "falta uma reserva por MAC para cada computador.",
            "o DHCP Discover é broadcast e não atravessa o roteador; deve-se configurar um agente de retransmissão (DHCP relay/ip helper) na interface da VLAN da agência, além de um escopo para 10.20.5.0/24.",
            "o servidor DHCP deve ser movido para a mesma VLAN de cada agência, pois o protocolo não funciona entre sub-redes em nenhuma hipótese."],
      gab="D",
      com="**Gabarito: D.** O **Discover é broadcast**, e roteadores não encaminham broadcast; sem resposta, o Windows assume um endereço **APIPA** (169.254.0.0/16). Solução: **DHCP relay** (ip helper-address) na interface da VLAN da agência, que repassa em unicast ao servidor, e um escopo para a sub-rede.\n\n(A) Exclusões reduzem a faixa distribuída; não resolvem. (B) Zona reversa é do DNS. (C) Reservas não são necessárias para receber endereço. (E) Com relay o DHCP atende várias sub-redes."),

    Q(E, "04", 16, sub="16.12", top="VPNs corporativas e acesso remoto seguro", k="srv-vpn-split",
      enun="Na VPN de acesso remoto dos funcionários em teletrabalho, a equipe de segurança exige que todo o tráfego do notebook corporativo, inclusive a navegação na internet, passe pelo túnel e pelos controles da empresa. Em vez de usar split tunneling, deve-se configurar",
      alts=["uma VPN site a site IPsec entre a casa de cada funcionário e o banco.",
            "o modo full tunnel no cliente VPN.",
            "o protocolo PPTP, por ser mais leve.",
            "o AH do IPsec, para cifrar o tráfego.",
            "uma VPN MPLS da operadora em cada residência."],
      gab="B",
      com="**Gabarito: B.** No **full tunnel**, todo o tráfego passa pela VPN; no **split tunneling** só o tráfego corporativo usa o túnel e o resto vai direto à internet, reduzindo o controle de segurança.\n\n(A) Site a site liga redes inteiras por gateways; acesso remoto usa cliente VPN. (C) O PPTP é inseguro. (D) O AH não cifra. (E) VPN MPLS é separação lógica na rede da operadora, inviável por residência."),

    Q(E, "04", 22, sub="22.1", top="Níveis de serviço e métricas de desempenho", k="srv-mtbf", tags=["calculo"],
      enun="Um serviço de autenticação apresentou, no último ano, tempo médio entre falhas (MTBF) de 495 horas e tempo médio de reparo (MTTR) de 5 horas. Usando a relação disponibilidade = MTBF ÷ (MTBF + MTTR), a disponibilidade do serviço é de",
      alts=["98,99%.",
            "99,00%.",
            "99,50%.",
            "99,90%.",
            "1,00%."],
      gab="B",
      com="**Gabarito: B.** Disponibilidade = 495 ÷ (495 + 5) = 495 ÷ 500 = 0,99 = **99,00%**.\n\n(A) 98,99% vem de 1 − 5 ÷ 495, fórmula incorreta. (C) e (D) Não decorrem dos dados. (E) 1% é a **indisponibilidade** (5 ÷ 500).\n\nConta conferida em `tools/verificacao/agente4/verif_serv.py`."),

    Q(E, "04", 12, sub="12.5", top="Configuração, administração e logs de serviços", k="srv-journalctl",
      enun="Em um servidor Oracle Linux com systemd, o administrador quer acompanhar em tempo real as mensagens de log do serviço `httpd` e, separadamente, garantir que os arquivos de log em /var/log sejam rotacionados e compactados periodicamente. As ferramentas adequadas são, respectivamente,",
      alts=["`journalctl -u httpd -f` e logrotate.",
            "`dmesg -c` e crontab -r.",
            "`systemctl disable httpd` e rsync.",
            "`tail /etc/passwd` e gzip -d.",
            "`ss -tulpn` e logger."],
      gab="A",
      com="**Gabarito: A.** `journalctl -u httpd -f` mostra o journal do systemd filtrado pela unidade e o acompanha (*follow*); o **logrotate** faz a rotação e a compactação dos arquivos de log.\n\n(B) `dmesg -c` lê e limpa o buffer do kernel; `crontab -r` **apaga** o crontab. (C) `systemctl disable` desativa o serviço no boot; rsync copia arquivos. (D) /etc/passwd não é log, e `gzip -d` descompacta. (E) `ss -tulpn` lista portas em escuta; logger grava uma mensagem no syslog."),
]
